fn main() -> std::process::ExitCode {
    let fonts = StudioIntroMedia::prepare().expect("fonts");
    let dir = MediaDirectory::read_folder("output/fframes-studio-standee/choices-real/assets")
        .expect("standee assets");
    let assets = dir.process_media_source().expect("assets");
    let media = CombinedMediaProvider::from([&fonts as &dyn MediaProvider, &assets]);
    let surface = fframes_skia_renderer::SkiaCpuCtx::new(Choices::WIDTH, Choices::HEIGHT);
    let backend = fframes_skia_renderer::SkiaFFramesRenderer::new_cpu(
        &surface,
        fframes_skia_renderer::SkiaPipelineConfig::default(),
    )
    .expect("print renderer");
    fframes::cli::new(
        &Choices,
        RenderOptions {
            media: Some(&media),
            ..Default::default()
        },
    )
    .backend(backend)
    .run()
}
